import { Button } from "@/registry/erbium/ui/button";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/registry/erbium/ui/tooltip";

export default function TooltipExample() {
  return (
    <Tooltip>
      <TooltipTrigger render={<Button variant="outline">Hover</Button>} />
      <TooltipContent>
        <p>Add to library</p>
      </TooltipContent>
    </Tooltip>
  );
}

import TooltipExample from "../examples/tooltip-demo";

const Example = () => (
  <div className="w-full max-w-2xl min-w-72 p-4">
    <TooltipExample />
  </div>
);

export default Example;
